<?php
// user \dclass\devups\model\Model;

/**
 * @Entity @Table(name="user")
 * */
class User extends UserCore implements JsonSerializable, NotificationSerialize
{

    public static $currentid;
    /**
     * @Id @GeneratedValue @Column(type="integer")
     * @var int
     * */
    protected $id;

    /**
     * @Column(name="phonecode", type="string", length=5 , nullable=true )
     * @var string
     **/
    protected $phonecode;
    /**
     * @Column(name="profile", type="string", length=255 , nullable=true )
     * @var string
     **/
    protected $profile;

    /**
     * @Column(name="birthdate", type="date", nullable=true )
     * @var string
     **/
    protected $birthdate;

    /**
     * @Column(name="available", type="integer", nullable=true )
     * @var string
     **/
    protected $available;

    /**
     * @ManyToOne(targetEntity="\Country")
     * @JoinColumn(onDelete="set null")
     * @var \Country
     */
    public $country;
 
    /**
     * @Column(name="avatar", type="text" , nullable=true)
     * @var string
     **/
    protected $avatar; 
    public function __construct($id = null)
    {

        if ($id) {
            $this->id = $id;
        }
 
        $this->country = new Country(); 
    }


    public function setActivationcode($activationcode)
    {

        $this->activationcode = sha1($activationcode);
        $this->activationcode_expired_at = date("Y-m-d H:i:s", strtotime("+3 hours", strtotime(date("Y-m-d H:i:s"))));
    }

    /**
     * Genere un code numerique (6 chiffres par defaut) pour l'activation
     * de compte, avec un generateur cryptographiquement sur. Le code en
     * clair n'est jamais stocke : setActivationcode() le hache.
     */
    public static function generatecode(int $length = 6): string
    {
        $code = '';
        for ($i = 0; $i < $length; $i++) {
            $code .= (string)random_int(0, 9);
        }
        return $code;
    }


    public static function sanitizePhonenumber($phonenumber, $phone_code)
    {
        $telephone = str_replace("+" . $phone_code, "", "+" . $phonenumber);
        return str_replace("+", "", $telephone);
    }

    public function srcProfile($p = '')
    {
        return Dfile::show($p . $this->profile, 'user');
    }

    public function __delete($exec = true)
    {

        if ($this->profile) {
            Dfile::deleteFile($this->profile, 'user');
            Dfile::deleteFile('50_' . $this->profile, 'user');
        }
        Push_subscription::where('user_id', $this->id)->delete(); 
        return parent::__delete($exec); // TODO: Change the autogenerated stub
    }


    /**
     * return the phonenumber with the country phone code.
     * @return string
     */
    public function getTelephone()
    {
        return $this->phonecode . $this->phonenumber;
    }

    public function notificationData()
    {
        return [
            'firstname' => $this->firstname,
            //'spacekola_ref' => $this->spacekola_ref,
            'lastname' => $this->lastname,
            'email' => $this->email,
        ];
    }

    public function uploadProfile($file = "profile")
    {

        $dfile = self::Dfile($file);
        if (!$dfile->errornofile) {

            $filedir = "user/";
            if ($this->profile) {
                Dfile::deleteFile($this->profile, 'user');
                Dfile::deleteFile('50_' . $this->profile, 'user');
            }
            $url = $dfile
                ->hashname()
                //->saveoriginal(false)
                ->addresize([50, 50], "50_")
                ->addresize([150, 150], "")
                ->moveto($filedir);

            if (!$url['success']) {
                return array(
                    'success' => false,
                    'error' => $url
                );
            }

            $this->profile = $url['file']['hashname'];
            if ($this->id) {
                $this->avatar = '';
                $this->__update();
            }
        }
    }


    public function showProfile()
    {
        $url = Dfile::show($this->profile, "user");
        return Dfile::fileadapter($url, "user");
    }


    public function dataSerialize()
    {
        return [
            'id' => $this->id,
            'username' => $this->username,
            'profile' => $this->profile,
            'src_profile' => $this->profile ? $this->srcProfile() : null,
            'avatar' => $this->avatar,
            'firstname' => $this->firstname,
            'lastname' => $this->lastname,
        ];
    } 

    #[\ReturnTypeWillChange]
    public function jsonSerialize()
    {
        return [ 
            'src_profile' => $this->profile ? $this->srcProfile() : null,
        ] + parent::jsonSerialize();
    }

    /**
     * Champs jamais exposés par l'API (mot de passe, jetons de session,
     * clé API...). Restent lisibles normalement sur l'objet PHP le temps
     * d'une requête (authentification, panneau d'administration) — seule
     * la sérialisation vers dvserialised/jsonSerialize() est filtrée.
     *
     * Liste blanche volontairement absente ici : on retire les champs
     * connus comme sensibles plutôt que d'énumérer tout ce qui est
     * autorisé, pour ne pas casser les nombreux champs déjà consommés
     * par la v1 (voir memory_2026-09-15_v3.md pour le recensement).
     */
    private const SENSITIVE_FIELDS = [
        'password',
        'activationcode',
        'api_key',
        'session_token',
        'devices',
    ];

    private function stripSensitiveFields()
    {
        foreach (self::SENSITIVE_FIELDS as $field) {
            unset($this->dvserialised[$field]);
        }
    }

    /**
     * Liste BLANCHE du profil public (`GET /user/:id` consulte par quelqu'un
     * d'autre que le titulaire du compte).
     *
     * Une liste blanche plutot que la liste noire self::SENSITIVE_FIELDS :
     * celle-ci est GLOBALE et sert aussi GET /user/me, ou email, telephone et
     * date de naissance sont legitimes puisqu'il s'agit de son propre compte.
     *
     * Une application qui enrichit User (compteurs, relations...) etend cette
     * liste dans sa propre sous-classe ou surcharge restrictToPublicProfile().
     */
    private const PUBLIC_PROFILE_FIELDS = [
        'id',
        'username',
        'firstname',
        'lastname', 
    ];

    /**
     * Relations autorisees sur un profil public. jsonSerialize() ajoute les
     * relations chargees ($this->with) EN PLUS de dvserialised : filtrer
     * dvserialised seul ne suffit donc pas a retirer une relation sensible.
     *
     * `country` est conserve (donnee non personnelle).
     */
    private const PUBLIC_PROFILE_RELATIONS = ['country'];

    /**
     * Reduit le JSON serialise a la liste blanche ci-dessus. A appeler
     * UNIQUEMENT pour un profil public, c'est-a-dire quand le demandeur n'est
     * pas le titulaire du compte - voir UserFrontController::detail().
     * `GET /user/me` et la consultation de son propre compte gardent la
     * serialisation complete, moins SENSITIVE_FIELDS.
     *
     * Deux filtrages, pas un : les champs plats (dvserialised) ET les
     * relations chargees ($this->with) - voir le commentaire sur
     * PUBLIC_PROFILE_RELATIONS.
     */
    public function restrictToPublicProfile()
    {
        foreach (array_keys($this->dvserialised) as $field) {
            if (!in_array($field, self::PUBLIC_PROFILE_FIELDS, true)) {
                unset($this->dvserialised[$field]);
            }
        }

        foreach ($this->with as $key => $relation) {
            if (!in_array($relation, self::PUBLIC_PROFILE_RELATIONS, true)) {
                unset($this->with[$key]);
            }
        }

        return $this;
    }

    /**
     * Point d'entrée central pour l'hydratation "top niveau" (ex.
     * User::find($id), GET /user/:id, GET /user/me). Filtre après coup
     * plutôt qu'avant : hydrateData() du parent a besoin de peupler
     * $this->password normalement (comparaisons sha1() ailleurs dans le
     * contrôleur), seul dvserialised (ce qui part en JSON) est nettoyé.
     */
    public function hydrateData($flowBD, $id_lang, $without, $custom_column_keys, $with_lang)
    {
        parent::hydrateData($flowBD, $id_lang, $without, $custom_column_keys, $with_lang);
        $this->stripSensitiveFields();
        return $this;
    }

    /**
     * Même filtrage pour un User chargé comme RELATION imbriquée d'une
     * autre entité (post.user, comment.user, ...). hydrateMatch() n'a pas de paramètre
     * $without comme hydrateData() — sans cette surcharge, une relation
     * `with('user')` sans liste de colonnes explicite pourrait fuiter les
     * mêmes champs que GET /user/:id.
     */
    public function hydrateMatch($flowDB, $entity, $with_lang)
    {
        parent::hydrateMatch($flowDB, $entity, $with_lang);
        $this->stripSensitiveFields();
    } 


    public function showAction($btarray)
    {
        return "<a class='btn btn-info' href='" . User::classpath('user/detail?id=') . $this->id . "'> Detail</a>";
    } 
}
